module Controller_2_Gates_1Hot(  output 		Ready, Load_regs, Add_shift,  input 		Start, Zero, clock, reset_b);  wire w1, w2, w3, w4;  wire T0, T1;  wire set;  assign Ready = T0;  assign Add_shift = T1;  and (Load_regs, T0, Start);  not (set, reset_b);  DFF_S M0 (T0, D0, clock, set);		// Note: reset action must initialize S_idle = 2'b01  DFF M1 (T1, D1, clock, reset_b);  not (Start_b, Start);  not (Zero_b, Zero);  and (w1, T0, Start_b);  and (w2, T1, Zero);  or (D0, w1, w2);  and (w3, T0, Start);  and (w4, T1, Zero_b);  or (D1, w3, w4);endmodulemodule DFF (output reg Q, input D, clock, reset_b);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) Q <= 0;    else Q <= D;endmodulemodule DFF_S (output reg Q, input D, clock, set);  always @ (posedge clock, posedge set)    if (set == 1) Q <= 1;    else Q <= D;endmodule